def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    factors = []
    d = 2
    temp = a
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)

    if len(factors) == 3:
        is_prime = True
        for factor in factors:
            if factor <= 1:
                is_prime = False
                break
            for i in range(2, int(factor**0.5) + 1):
                if factor % i == 0:
                    is_prime = False
                    break
            if not is_prime:
                break
        if is_prime:
            return True
        else:
            return False
    else:
        return False
